export type { MetaProvider, ModelChoice } from './pricing.ts';

export const MODAL_MUSE_SPARK_OPEN_MODEL: 'meta-models/Muse-Spark-Open-816B-A42B' =
  'meta-models/Muse-Spark-Open-816B-A42B';

